(root/'admin.js').write_text(admin_js,encoding='utf-8')

# Fix a mistaken helper in content field calls: field signature (label,key,val,area,cls); current call passes cls as area. Normalize by replacing the mapping expression.
p=root/'admin.js'; t=p.read_text(encoding='utf-8')
t=t.replace("field(x[0],x[1],x[2]||'',String(x[2]||'').length>100?'full':'' )", "field(x[0],x[1],x[2]||'',String(x[2]||'').length>100,'full')")
p.write_text(t,encoding='utf-8')

# Patch index to load CMS values for visible hardcoded sections not covered by dynamic.js.
idx=(root/'index.html').read_text(encoding='utf-8')
patch=r'''<script>
window.addEventListener('beehouse:ready',()=>{const s=window.BeeHouseCMS.site,c=s.content?.home||{};const set=(sel,v,html=false)=>{const e=document.querySelector(sel);if(e&&v!=null)(html?e.innerHTML=e.innerHTML.replace(/[^]*?/,''):e.textContent=v)};document.querySelector('.badge-pill-soft')&&(document.querySelector('.badge-pill-soft').textContent=c.portfolioBadge||'ผลงาน');document.querySelector('.section-title')&&(document.querySelectorAll('.section-title')[0].textContent=c.portfolioTitle||'โปรเจกต์จากรังของเรา');document.querySelectorAll('.section-desc')[0]&&(document.querySelectorAll('.section-desc')[0].textContent=c.portfolioDescription||'');document.querySelectorAll('.section-title')[1]&&(document.querySelectorAll('.section-title')[1].textContent=c.partnerTitle||'ร้านค้าพาร์ทเนอร์');document.querySelectorAll('.section-desc')[1]&&(document.querySelectorAll('.section-desc')[1].textContent=c.partnerDescription||'');});
</script>'''
idx=idx.replace('</body>',patch+'\n</body>')
(root/'index.html').write_text(idx,encoding='utf-8')

# README add static CMS instructions
readme=(root/'README.md').read_text(encoding='utf-8')
readme+='''\n\n## BeeHouse Admin CMS (GitHub Pages)\n- Admin dashboard now controls site text, hero, tabs, stats, news, navigation, buttons, feature flags, jobs, portfolio, partners, theme, applications/evaluations, contacts, audit logs, and JSON backup/import.\n- On GitHub Pages, browser storage is local to the Admin device. Use **Export site.json** and replace the repository `site.json` to publish changes to all visitors.\n- Applications submitted from GitHub Pages are also local to the browser. For multi-user shared applications, connect the existing Express API/backend or another database service.\n'''
(root/'README.md').write_text(readme,encoding='utf-8')

# Rezip
out=Path('/mnt/data/BeeHouse_Admin_CMS_GitHubPages.zip')
if out.exists(): out.unlink()
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
    for p in root.rglob('*'):
        if p.is_file(): z.write(p,p.relative_to(root))
print(out)
